record BridgeId(int priority, long mac) implements Comparable<BridgeId> {
  public int compareTo(BridgeId o) { int c = Integer.compare(priority, o.priority); return c != 0 ? c : Long.compareUnsigned(mac, o.mac); }
}
record Bpdu(BridgeId root, int cost, BridgeId sender, int portId) {}
static final Comparator<Bpdu> BETTER = Comparator.comparing(Bpdu::root)
    .thenComparingInt(Bpdu::cost)
    .thenComparing(Bpdu::sender)
    .thenComparingInt(Bpdu::portId);
// BETTER.compare(a, b) < 0 → a jest lepsze (niższe wartości wygrywają).
